// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(bytes32 guess, address actor) public {
        vm.assume(actor != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(guess);

        uint256 lockBlock = block.number;
        // Reference: stored block is lockBlock + 1, so settle succeeds at lockBlock + 2.
        // Mutant: stored block is lockBlock + 2, so settle reverts at lockBlock + 2.
        vm.roll(lockBlock + 2);
        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "settle must succeed two blocks after locking in a guess");
    }
}
